CREATE FUNCTION pagar(p_reserva bigint, p_medio text)
RETURNS void
LANGUAGE plpgsql
AS $$
DECLARE
  r reservas%ROWTYPE;
BEGIN
  SELECT * INTO r FROM reservas WHERE id = p_reserva FOR UPDATE;
  IF NOT FOUND OR r.estado <> 'pendiente' THEN
    RAISE EXCEPTION 'la reserva % no está pendiente de pago', p_reserva;
  END IF;
  INSERT INTO pagos (reserva_id, tipo, monto, medio) VALUES (p_reserva, 'cobro', r.precio, p_medio);
  UPDATE reservas SET estado = 'confirmada' WHERE id = p_reserva;
END;
$$;
SELECT id AS nueva FROM reservar(15, 2, '2026-10-05 19:00') \gset
SELECT pagar(:nueva, 'debito');
SELECT r.id, r.estado, r.precio, p.tipo, p.monto, p.medio
FROM reservas r JOIN pagos p ON p.reserva_id = r.id
WHERE r.id = :nueva;
-- Pagar dos veces: la reserva ya no está pendiente
SELECT pagar(:nueva, 'debito');

CREATE TABLE auditoria (
  id        bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tabla     text NOT NULL,
  operacion text NOT NULL,
  antes     jsonb,
  despues   jsonb,
  usuario   text NOT NULL DEFAULT current_user,
  en        timestamptz NOT NULL DEFAULT clock_timestamp()
);
CREATE FUNCTION auditar() RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  INSERT INTO auditoria (tabla, operacion, antes, despues)
  VALUES (TG_TABLE_NAME, TG_OP,
          CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) END,
          CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) END);
  RETURN NULL;
END;
$$;
CREATE TRIGGER recintos_auditoria AFTER INSERT OR UPDATE OR DELETE ON recintos
  FOR EACH ROW EXECUTE FUNCTION auditar();
CREATE TRIGGER tarifas_auditoria AFTER INSERT OR UPDATE OR DELETE ON tarifas
  FOR EACH ROW EXECUTE FUNCTION auditar();
