       a.antes -> c.campo AS antes, a.despues -> c.campo AS despues
FROM auditoria a
CROSS JOIN LATERAL (SELECT key AS campo FROM jsonb_each(coalesce(a.despues, a.antes))) AS c
WHERE a.antes -> c.campo IS DISTINCT FROM a.despues -> c.campo
ORDER BY a.id, c.campo;

CREATE FUNCTION avisar_lista_espera() RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
  v_socio integer;
BEGIN
  SELECT socio_id INTO v_socio
  FROM lista_espera
  WHERE recinto_id = NEW.recinto_id AND periodo && NEW.periodo
  ORDER BY creada_en, id
  LIMIT 1;
  IF FOUND THEN
    PERFORM pg_notify('lista_espera',
      json_build_object('reserva', NEW.id, 'recinto', NEW.recinto_id,
                        'inicio', lower(NEW.periodo), 'avisar_a', v_socio)::text);
  END IF;
  RETURN NULL;
END;
$$;
